  const canManage=role==='admin'||role==='warehouse';
  const requestItems=x=>x.items?.length?x.items.map(item=>esc(item.name)+' — '+esc(item.quantity)+' '+esc(item.unit||'un')).join('<br>'):esc(x.item||'Material');
  const categoryDescriptions={'CFTV':'Câmeras, gravadores DVR/NVR, fontes e conectores de vídeo.','Controle de acesso':'Leitores, fechaduras, catracas, cartões e controles de acesso.','Automação de portões':'Motores, centrais, controles remotos e cancelas.','Cabeamento':'Cabos, conectores, canaletas e acessórios de instalação.','Alarmes':'Centrais, sensores, sirenes e acessórios de alarme.','Elétrica':'Fontes, fios, conectores e componentes elétricos.','Ferramentas':'Ferramentas e instrumentos usados nas instalações e manutenções.','Outros':'Materiais que não se encaixam nas categorias anteriores.'};
